using System;
using System.Collections.Generic;
using System.Globalization;
using Microsoft.Win32;
namespace ModeSwitchPrice {
 // The game's own text language (Game.ini "Language", e.g. "kr", "jp", "ch"): titles are read with that OCR and
 // matched against tarkov.dev names in that language, whatever BlueAsh's UI language is.
 public static class GameLanguage {
  static readonly string[][] map={
   new[]{"kr","ko","ko","ko-KR"},new[]{"en","en","en","en-US"},new[]{"jp","ja","ja","ja-JP"},new[]{"ch","zh","zh-Hans","zh-CN"},new[]{"ru","ru","ru","ru-RU"},
   new[]{"ge","de","de","de-DE"},new[]{"fr","fr","fr","fr-FR"},new[]{"es","es","es","es-ES"},new[]{"es-mx","es","es","es-MX"},new[]{"it","it","it","it-IT"},
   new[]{"po","pl","pl","pl-PL"},new[]{"pt","pt","pt","pt-PT"},new[]{"hu","hu","hu","hu-HU"},new[]{"tu","tr","tr","tr-TR"},new[]{"sk","sk","sk","sk-SK"},new[]{"ro","ro","ro","ro-RO"}};
  static string[] Row(string api){foreach(var r in map)if(r[1]==api)return r;return map[1];}
  // tarkov.dev locale of the game text; English when the setting is missing or unknown (e.g. Czech, not on tarkov.dev).
  public static string Api(string gameIni){
   try{var m=System.Text.RegularExpressions.Regex.Match(System.IO.File.ReadAllText(gameIni),"\"Language\"\\s*:\\s*\"([^\"]+)\"");
    if(m.Success){var v=m.Groups[1].Value.ToLowerInvariant();foreach(var r in map)if(r[0]==v)return r[1];}}catch{}
   return "en";}
  public static string OcrTag(string api){return Row(api)[2];}
  // Windows optional feature that adds this OCR language (Add-WindowsCapability).
  public static string Capability(string api){return "Language.OCR~~~"+Row(api)[3]+"~0.0.1.0";}
 }
 // UI language only: OCR inputs, item matching and on-disk protocol values keep their original language.
 public static class Language {
  // Row order of every catalog entry below: ko, zh-CN, ja, en, ru, then the extra languages (source/i18n_extend.mjs).
  public static readonly string[] Codes={"ko","zh-CN","ja","en","ru","es","pt-BR","de","fr","it","pl","tr","zh-TW"};
  static string code=Read();
  static readonly Dictionary<string,string[]> words=Build();
  public static string Code{get{return code;}set{code=Normalize(value);}}
  public static string Normalize(string value){foreach(var c in Codes)if(c.Equals(value,StringComparison.OrdinalIgnoreCase))return c;return "ko";}
  static string Read(){try{using(var k=Registry.CurrentUser.OpenSubKey("Software\\ModeSwitch"))return Normalize(k==null?null:Convert.ToString(k.GetValue("Language")));}catch{return "ko";}}
  public static void Reload(){Code=Read();}
  public static string ApiLocale{get{return code=="zh-CN"||code=="zh-TW"?"zh":code=="pt-BR"?"pt":code;}}
  public static CultureInfo Culture{get{return CultureInfo.GetCultureInfo(code);}}
  public static string FontName{get{return code=="zh-CN"?"Microsoft YaHei UI":code=="zh-TW"?"Microsoft JhengHei UI":code=="ja"?"Yu Gothic UI":code=="ko"?"Malgun Gothic":"Segoe UI";}}
  public static string[] Keys{get{var keys=new string[words.Count];words.Keys.CopyTo(keys,0);return keys;}}
  public static bool Contains(string source){return words.ContainsKey(source);}
  public static string T(string source,params object[] args){string[] row;string value=words.TryGetValue(source,out row)?row[Array.IndexOf(Codes,code)]:source;return args.Length==0?value:string.Format(Culture,value,args);}
  // Windows/.NET diagnostics follow the OS language. Keep authored translations; show invariant technical
  // identifiers for other errors so a Korean Windows installation does not mix Korean into another UI language.
  public static string Error(Exception error){
   if(error==null)return "";if(code=="ko")return error.Message;
   var cause=error.GetBaseException();int language=Array.IndexOf(Codes,code);
   foreach(var row in words.Values)if(row[language]==cause.Message)return cause.Message;
   return cause.GetType().Name+" (0x"+cause.HResult.ToString("X8",CultureInfo.InvariantCulture)+")";
  }
  static Dictionary<string,string[]> building;
  // Short rows (not yet extended) fall back to English for the extra languages.
  static void add(params string[] v){var row=new string[Codes.Length];for(int i=0;i<row.Length;i++)row[i]=i<v.Length?v[i]:v[3];building.Add(v[0],row);}
  static Dictionary<string,string[]> Build(){var d=new Dictionary<string,string[]>();building=d;
   add("켜는 중 · 글자 인식(OCR)을 준비하고 있습니다.","正在启用 · 正在准备文字识别（OCR）。","起動中 · 文字認識（OCR）を準備しています。","Starting · Preparing text recognition (OCR).","Запуск · Подготовка распознавания текста (OCR).","Iniciando · Preparando el reconocimiento de texto (OCR).","Iniciando · Preparando o reconhecimento de texto (OCR).","Startet · Texterkennung (OCR) wird vorbereitet.","Démarrage · Préparation de la reconnaissance de texte (OCR).","Avvio · Preparazione del riconoscimento testo (OCR).","Uruchamianie · Przygotowanie rozpoznawania tekstu (OCR).","Başlatılıyor · Metin tanıma (OCR) hazırlanıyor.","啟動中 · 正在準備文字辨識（OCR）。");
